import{_ as i,C as r,o as n,c as o,a5 as a,E as s}from"./chunks/framework.BF53ZjCA.js";const b=JSON.parse('{"title":"Round Brilliant Cut","description":"","frontmatter":{"title":"Round Brilliant Cut","cutting":"brilliant-cut"},"headers":[],"relativePath":"cutting/brilliant-cut.md","filePath":"cutting/brilliant-cut.md","lastUpdated":1790876393000}'),l={name:"cutting/brilliant-cut.md"};function d(c,e,u,p,h,m){const t=r("FacetDiagram");return n(),o("div",null,[e[0]||(e[0]=a('<h1 id="round-brilliant-cut" tabindex="-1">Round Brilliant Cut <a class="header-anchor" href="#round-brilliant-cut" aria-label="Permalink to &quot;Round Brilliant Cut&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Round brilliant is a classic faceting style, most associated with diamond. Marcel Tolkowsky&#39;s 1919 study of related proportions made it a reference for discussing table, crown, girdle, and pavilion relationships. For transparent materials suited to this proportion system, those relationships can improve brightness, scintillation, and fire; they are not a universal prescription.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-brilliant-cut-en"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-brilliant-cut-en">Boundary &amp; Safety</h2><p>The proportions and facet counts here establish terminology and an analysis starting point, not a fixed process recipe for every material. The actual plan requires review against RI, rough shape, inclusions, durability, equipment, and cutter judgement. </p></aside><h2 id="structural-diagram" tabindex="-1">Structural Diagram <a class="header-anchor" href="#structural-diagram" aria-label="Permalink to &quot;Structural Diagram&quot;">​</a></h2>',5)),s(t,{locale:"en"}),e[1]||(e[1]=a('<h2 id="case-flow" tabindex="-1">Case Flow <a class="header-anchor" href="#case-flow" aria-label="Permalink to &quot;Case Flow&quot;">​</a></h2><blockquote><p>Teaching case (demonstration): this shows how proportions enter analysis, not the final plan for a specific stone.</p></blockquote><h3 id="_1-confirm-the-material-boundary" tabindex="-1">1. Confirm the material boundary <a class="header-anchor" href="#_1-confirm-the-material-boundary" aria-label="Permalink to &quot;1. Confirm the material boundary&quot;">​</a></h3><p>Record RI, transparency, rough shape, and durability risks. If the material is not suited to a round-brilliant starting point, return to outline and durability trade-offs instead of forcing angle values.</p><h3 id="_2-establish-a-proportion-starting-point" tabindex="-1">2. Establish a proportion starting point <a class="header-anchor" href="#_2-establish-a-proportion-starting-point" aria-label="Permalink to &quot;2. Establish a proportion starting point&quot;">​</a></h3><p>Use the table, crown, girdle, and pavilion relationships to make a first model, then inspect expected brilliance, scintillation, and fire. The 57/58 count standardizes terminology; it does not prove finished quality.</p><h3 id="_3-verify-observable-outcomes" tabindex="-1">3. Verify observable outcomes <a class="header-anchor" href="#_3-verify-observable-outcomes" aria-label="Permalink to &quot;3. Verify observable outcomes&quot;">​</a></h3><p>Under consistent light, viewing direction, and background, record leakage, dark zones, asymmetry, or weak girdle areas. Keep observed effects separate from possible causes so one observation is not turned into a grade.</p><h3 id="_4-stop-conditions" tabindex="-1">4. Stop conditions <a class="header-anchor" href="#_4-stop-conditions" aria-label="Permalink to &quot;4. Stop conditions&quot;">​</a></h3><p>When proportions conflict with RI, inclusions, or durability, stop giving one “best” answer. Keep candidate plans and ask a cutter to review them against the rough and equipment.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>The common count is 57 facets without the culet: 1 table + 32 other crown facets + 24 pavilion facets; including the culet makes 58.</li><li>Table diameter ~53–58%; crown angle 34–35°; pavilion angle 40.75–41.2°.</li><li>Girdle must balance durability against weight retention.</li><li>Brilliance depends on precise proportions; errors create &quot;windows&quot; of light leakage.</li><li>These proportions are a starting point, not a prescription for every gem; RI, dispersion, shape, and durability change the target.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Cut</th><th>Note</th></tr></thead><tbody><tr><td>diamond</td><td>Round Brilliant, 57f</td><td>Example entry</td></tr><tr><td>zircon</td><td>Round Brilliant</td><td>High-dispersion material example</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA: Gem Cutting Styles — Definitions</a><span>Definitions of outlines, facet arrangements, step cuts, cabochons, and carving styles</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors and Cut Quality</a><span>Cut trade-offs among proportions, symmetry, polish, rough limitations, and appearance</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA: Diamond Cut</a><span>Round-brilliant table, crown, girdle, pavilion, and the 57/58-facet count</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>How colored-stone cutting weighs color, durability, inclusions, and fractures</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-brilliant-cut-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-brilliant-cut-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>The common round-brilliant count is 57 facets without the culet and 58 including it.</span><small>GIA: Diamond Cut</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Proportions should be an analysis starting point rather than a fixed prescription for every gem.</span><small>GIA: Diamond Cut; GIA: Colored Gemstone Value Factors and Cut Quality</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>The teaching case separates a proportion starting point from observable review under consistent conditions.</span><small>GIA: Diamond Cut; GIA: Colored Gemstone Value Factors and Cut Quality</small></li></ul></aside><p><em>See the <a href="./intro.html">cutting overview</a>.</em></p>',17))])}const f=i(l,[["render",d]]);export{b as __pageData,f as default};
